function punishmentNumber(n) {
  function canSplit(digits, start, remaining) {
    if (start === digits.length) {
      return remaining === 0;
    }
    let piece = 0;
    for (let end = start; end < digits.length; end++) {
      piece = piece * 10 + Number(digits[end]);
      if (piece > remaining) {
        break;
      }
      if (canSplit(digits, end + 1, remaining - piece)) {
        return true;
      }
    }
    return false;
  }

  let total = 0;
  for (let i = 1; i <= n; i++) {
    const square = i * i;
    if (canSplit(String(square), 0, i)) {
      total += square;
    }
  }
  return total;
}

