function punishmentNumber(n) {
  let sum = 0;
  for (let i = 1; i <= n; i++) {
    const text = String(i * i);
    const gaps = text.length - 1;
    // Each bit of mask says whether to cut between two neighbouring digits.
    for (let mask = 0; mask < (1 << gaps); mask++) {
      let pieces = 0;
      let from = 0;
      for (let g = 0; g < gaps; g++) {
        if (mask & (1 << g)) {
          pieces += parseInt(text.slice(from, g + 1), 10);
          from = g + 1;
        }
      }
      pieces += parseInt(text.slice(from), 10);
      if (pieces === i) {
        sum += i * i;
        break;
      }
    }
  }
  return sum;
}

